import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import com.eviware.soapui.support.XmlHolder
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

// Estado del simulador: un archivo JSON dentro del contenedor (se pierde al reiniciarlo).
def archivo = new File(System.getenv("ARCHIVO_GUIAS") ?: "/tmp/guias-coordinadora.json")
def leer = { archivo.exists() ? new JsonSlurper().parseText(archivo.getText("UTF-8")) : [consecutivo: 0, recogidas: 0, guias: [:]] }
def guardar = { datos -> archivo.setText(JsonOutput.toJson(datos), "UTF-8") }
def ahora = { LocalDateTime.now(ZoneId.of("America/Bogota")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")) }
def fallo = { String mensaje -> "<soapenv:Fault><faultcode>soapenv:Client</faultcode><faultstring>${mensaje}</faultstring></soapenv:Fault>".toString() }
def solicitud = new XmlHolder(mockRequest.requestContent)
solicitud.declareNamespace("g", "http://coordinadora.simulada/guias")

def origen = solicitud.getNodeValue("//g:ciudadOrigen")
def destino = solicitud.getNodeValue("//g:ciudadDestino")
if (!(origen ==~ /\d{8}/) || !(destino ==~ /\d{8}/)) {
    requestContext.cuerpo = fallo("Ciudad no válida: se espera el código DIVIPOLA de 8 dígitos")
    return
}
def pesos = solicitud.getNodeValues("//g:piezas/g:pesoGr")
def largos = solicitud.getNodeValues("//g:piezas/g:largoCm")
def anchos = solicitud.getNodeValues("//g:piezas/g:anchoCm")
def altos = solicitud.getNodeValues("//g:piezas/g:altoCm")
// Peso liquidado: el mayor entre el real y el volumétrico (400 kg/m3 = 0,4 g/cm3), pieza por pieza.
long liquidado = 0
for (int i = 0; i < pesos.length; i++) {
    long real = pesos[i] as long
    long volumen = Math.round((largos[i] as long) * (anchos[i] as long) * (altos[i] as long) * 0.4d)
    liquidado += Math.max(real, volumen)
}
long kilos = (long) Math.ceil(liquidado / 1000.0d)
double factor = origen == destino ? 1.0d : 1.3d
long valor = Math.round((9000 + 6000 * kilos) * factor)
int dias = origen == destino ? 1 : 3
requestContext.cuerpo = "<g:CotizarFleteRespuesta><g:valorFlete>${valor}</g:valorFlete><g:pesoLiquidadoGr>${liquidado}</g:pesoLiquidadoGr><g:diasEntrega>${dias}</g:diasEntrega></g:CotizarFleteRespuesta>".toString()

import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import com.eviware.soapui.support.XmlHolder
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

// Estado del simulador: un archivo JSON dentro del contenedor (se pierde al reiniciarlo).
def archivo = new File(System.getenv("ARCHIVO_GUIAS") ?: "/tmp/guias-coordinadora.json")
def leer = { archivo.exists() ? new JsonSlurper().parseText(archivo.getText("UTF-8")) : [consecutivo: 0, recogidas: 0, guias: [:]] }
def guardar = { datos -> archivo.setText(JsonOutput.toJson(datos), "UTF-8") }
def ahora = { LocalDateTime.now(ZoneId.of("America/Bogota")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")) }
def fallo = { String mensaje -> "<soapenv:Fault><faultcode>soapenv:Client</faultcode><faultstring>${mensaje}</faultstring></soapenv:Fault>".toString() }
def solicitud = new XmlHolder(mockRequest.requestContent)
solicitud.declareNamespace("g", "http://coordinadora.simulada/guias")

synchronized (System) {
    def datos = leer()
    datos.consecutivo = (datos.consecutivo ?: 0) + 1
    def numero = String.format("9%011d", datos.consecutivo as long)
    datos.guias[numero] = [
        referencia   : solicitud.getNodeValue("//g:referencia"),
        ciudadOrigen : solicitud.getNodeValue("//g:ciudadOrigen"),
        ciudadDestino: solicitud.getNodeValue("//g:destinatario/g:ciudad"),
        estados      : [[codigo: "1", descripcion: "Guía generada", fecha: ahora()]]
    ]
    guardar(datos)
    requestContext.cuerpo = "<g:GenerarGuiaRespuesta><g:codigoRemision>${numero}</g:codigoRemision></g:GenerarGuiaRespuesta>".toString()
}

import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import com.eviware.soapui.support.XmlHolder
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

// Estado del simulador: un archivo JSON dentro del contenedor (se pierde al reiniciarlo).
def archivo = new File(System.getenv("ARCHIVO_GUIAS") ?: "/tmp/guias-coordinadora.json")
def leer = { archivo.exists() ? new JsonSlurper().parseText(archivo.getText("UTF-8")) : [consecutivo: 0, recogidas: 0, guias: [:]] }
def guardar = { datos -> archivo.setText(JsonOutput.toJson(datos), "UTF-8") }
def ahora = { LocalDateTime.now(ZoneId.of("America/Bogota")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")) }
def fallo = { String mensaje -> "<soapenv:Fault><faultcode>soapenv:Client</faultcode><faultstring>${mensaje}</faultstring></soapenv:Fault>".toString() }
def solicitud = new XmlHolder(mockRequest.requestContent)
solicitud.declareNamespace("g", "http://coordinadora.simulada/guias")

synchronized (System) {
    def datos = leer()
    def numero = solicitud.getNodeValue("//g:codigoRemision")
    def guia = datos.guias[numero]
    if (guia == null) {
        requestContext.cuerpo = fallo("Remisión no encontrada: ${numero}")
        return
    }
    def franja = solicitud.getNodeValue("//g:franja")
    if (!(franja in ["AM", "PM"])) {
        requestContext.cuerpo = fallo("Franja no válida: ${franja} (se espera AM o PM)")
        return
    }
    datos.recogidas = (datos.recogidas ?: 0) + 1
    def recogida = String.format("REC-%06d", datos.recogidas as long)
    guia.recogida = [numero: recogida, fecha: solicitud.getNodeValue("//g:fechaRecogida"), franja: franja]
    guardar(datos)
    requestContext.cuerpo = "<g:ProgramarRecogidaRespuesta><g:numeroRecogida>${recogida}</g:numeroRecogida></g:ProgramarRecogidaRespuesta>".toString()
}

import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import com.eviware.soapui.support.XmlHolder
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

// Estado del simulador: un archivo JSON dentro del contenedor (se pierde al reiniciarlo).
def archivo = new File(System.getenv("ARCHIVO_GUIAS") ?: "/tmp/guias-coordinadora.json")
def leer = { archivo.exists() ? new JsonSlurper().parseText(archivo.getText("UTF-8")) : [consecutivo: 0, recogidas: 0, guias: [:]] }
def guardar = { datos -> archivo.setText(JsonOutput.toJson(datos), "UTF-8") }
def ahora = { LocalDateTime.now(ZoneId.of("America/Bogota")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")) }
def fallo = { String mensaje -> "<soapenv:Fault><faultcode>soapenv:Client</faultcode><faultstring>${mensaje}</faultstring></soapenv:Fault>".toString() }
def solicitud = new XmlHolder(mockRequest.requestContent)
solicitud.declareNamespace("g", "http://coordinadora.simulada/guias")

def datos
synchronized (System) { datos = leer() }
def numero = solicitud.getNodeValue("//g:codigoRemision")
def guia = datos.guias[numero]
if (guia == null) {
    requestContext.cuerpo = fallo("Remisión no encontrada: ${numero}")
    return
}
def estados = guia.estados.collect { e ->
    "<g:estados><g:codigo>${e.codigo}</g:codigo><g:descripcion>${e.descripcion}</g:descripcion><g:fecha>${e.fecha}</g:fecha></g:estados>"
}.join("")
requestContext.cuerpo = "<g:ConsultarEstadoGuiaRespuesta><g:codigoRemision>${numero}</g:codigoRemision>${estados}</g:ConsultarEstadoGuiaRespuesta>".toString()

import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import com.eviware.soapui.support.XmlHolder
import java.time.LocalDateTime
import java.time.ZoneId
import java.time.format.DateTimeFormatter

// Estado del simulador: un archivo JSON dentro del contenedor (se pierde al reiniciarlo).
def archivo = new File(System.getenv("ARCHIVO_GUIAS") ?: "/tmp/guias-coordinadora.json")
def leer = { archivo.exists() ? new JsonSlurper().parseText(archivo.getText("UTF-8")) : [consecutivo: 0, recogidas: 0, guias: [:]] }
def guardar = { datos -> archivo.setText(JsonOutput.toJson(datos), "UTF-8") }
def ahora = { LocalDateTime.now(ZoneId.of("America/Bogota")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")) }
def fallo = { String mensaje -> "<soapenv:Fault><faultcode>soapenv:Client</faultcode><faultstring>${mensaje}</faultstring></soapenv:Fault>".toString() }
def solicitud = new XmlHolder(mockRequest.requestContent)
solicitud.declareNamespace("g", "http://coordinadora.simulada/guias")

def DESCRIPCIONES = ["1": "Guía generada", "2": "Recogida", "3": "En terminal de origen", "4": "En transporte",
                     "5": "En terminal de destino", "6": "En reparto", "7": "Entregada", "8": "Novedad",
                     "9": "Devuelta al remitente"]
synchronized (System) {
    def datos = leer()
    def numero = solicitud.getNodeValue("//g:codigoRemision")
    def guia = datos.guias[numero]
    if (guia == null) {
        requestContext.cuerpo = fallo("Remisión no encontrada: ${numero}")
        return
    }
    def codigo = solicitud.getNodeValue("//g:codigoEstado")
    guia.estados << [codigo: codigo, descripcion: DESCRIPCIONES[codigo] ?: "Estado de prueba sin descripción", fecha: ahora()]
    guardar(datos)
    requestContext.cuerpo = "<g:CambiarEstadoGuiaRespuesta><g:resultado>OK</g:resultado></g:CambiarEstadoGuiaRespuesta>"
}
